window.MONSTER_CHUNK_17 = [{"name":"Death Dog","cr":2,"xp":600,"alignment":"NE","size":"Large","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":13,"ac_touch":11,"ac_flat_footed":11,"ac_mods":"+2 Dex, +2 natural, -1 size","hp":22,"hd":"3d10+6","hdvalue":3,"fort":4,"ref":5,"will":11,"speed":[{"type":"land","speed":30}],"melee":"2 bites +4 (1d8+1 plus disease and trip)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"disease"}],"strength":13,"dexterity":15,"constitution":13,"intelligence":4,"wisdom":12,"charisma":6,"baseatk":3,"cmb":14,"cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":4},{"skill":"Survival","value":4}],"languages":["Goblin (can't speak)"],"environments":["warm deserts"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"incidental","description_visual":"This black-furred, two-headed dog is as large as a horse and has midnight-black eyes. Tiny worms crawl on its mangy hide.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Disease","kind":"Su","details":"Wormpox: Bite-Injury; save Fort DC 12; onset 1 day; frequency 1 day; effect 1 Con damage; cure 2 consecutive saves."}],"description":"Death dogs are disease-ridden nocturnal pack hunters. Said to be the risen corpses of dogs or hyenas animated by monster-worshiping cultists, they are actually living creatures infested with symbiotic worms. Capable of tracking their prey for miles across barren terrain, death dogs surround stronger creatures, attacking and retreating, allowing their infected bites to wear down an opponent until it is too weak to fight. A pack's territory may overlap with others of its kind without competition, though in lean times packs may skirmish over live prey or carrion. A death dog's saliva contains hundreds of tiny eggs that grow into flesh-devouring worms. The worms don't harm the death dog, but consume any creatures they come into contact with. A death dog's corpse is contagious for several days after its demise and may infect creatures that touch or eat it. Remove disease can kill a death dog's worms and remove its disease ability, but if allowed to associate with others of its kind, its quickly becomes reinfected. A typical death dog is 7 ft. long, stands 4 ft. tall at the shoulder, and weighs about 500 pounds. Death dogs may ally with hobgoblins and bugbears, though the goblinoids are not immune to the dogs' disease. Thus these alliances are often temporary.\n\nDEATH WORG\n\nIn the scrub borders between forests and deserts or plains and badlands, worgs and death dogs may mix. If a worg pack is resistant to disease, or an outcast worg takes control of a death dog pack, crossbreeding may occur. Most of these two-headed pups die before reaching adulthood, but those that survive are larger, tougher, smarter, and able to speak as well as a worg can (add the advanced creature simple template). These \"death worgs\" have worms infecting their brains, driving them mad with rage. Death worgs bully their packs into submission, raid caravans and humanoid settlements, and kill more than they can eat. Most death worgs live only a year or two into adulthood, slain in needless fights for dominance or dropping dead as their worm-ravaged brains stop working.","ecology":"","habitat_society":""},{"name":"Dire Bat","cr":2,"xp":600,"alignment":"N","size":"Large","type":"animal","init":2,"senses":[{"type":"blindsense","modifier":"40 ft."}],"ac":14,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 natural, -1 size","hp":22,"hd":"4d8+4","hdvalue":4,"fort":5,"ref":6,"will":4,"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"bite +5 (1d8+4)","space":"10 ft.","reach":"5 ft.","strength":17,"dexterity":15,"constitution":13,"intelligence":2,"wisdom":14,"charisma":6,"baseatk":3,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Stealthy"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":12},{"skill":"Stealth","value":4}],"organizations":["solitary","pair","colony (3-8)"],"treasure":"incidental","description_visual":"This giant, furry bat is nearly the size of an ox, with dark leathery wings that open wider than two men with arms outstretched.","group":"Bat","source":"PFRPG Bestiary","description":"The dire bat is usually found lairing in desolate areas, resting in caves or other secluded areas during the day and taking to the skies in search of prey at night. This immense creature has an average wingspan of 15 ft. and weighs roughly 200 pounds. The dire bat generally doesn't shelter in groups larger than eight, often living a solitary life. A dire bat prefers feeding on livestock and herd animals. Dire Bat Animal Companion Starting Statistics: Size Medium; Speed 20 ft., fly 40 ft. (good); AC +0 natural armor; Attack bite (1d6); Ability Scores Str 9, Dex 17, Con 9, Int 2, Wis 14, Cha 6; Special Qualities blindsense 40 ft. 7th-Level Advancement: Size Large; AC +3 natural armor; Attack bite (1d8); Ability Scores Str +8, Dex -2, Con +4.","ecology":"","habitat_society":""},{"name":"Doru","cr":2,"xp":600,"alignment":"NE","size":"Tiny","type":"outsider","subtypes":["div","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"},{"type":"see in darkness"}],"ac":18,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+3 Dex, +3 natural, +2 size","hp":16,"hd":"3d10","hdvalue":3,"fort":3,"ref":4,"will":10,"dr":"10/cold iron or good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10}],"sr":13,"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"bite +9 (1d4-1 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"suggestion"}]},{"frequency":"3/day","spells":[{"spell":"charm person"},{"spell":"minor image"}]},{"frequency":"1/week","spells":[{"spell":"commune"}]}],"strength":8,"dexterity":17,"constitution":10,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":3,"cmb":20,"cmb_special":"+4 vs. grapple","cmd":33,"feats":[{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Fly","value":15},{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":7},{"skill":"Spellcraft","value":6},{"skill":"Stealth","value":17}],"languages":["Abyssal","Celestial","Infernal","telepathy 100 ft."],"environments":["any (Abaddon)"],"organizations":["solitary"],"treasure":"none","description_visual":"This disembodied and bestial head covered in lashing hair and curling horns flies through the air.","group":"Div","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 11; frequency 1/round for 6 rounds; effect 1d2 Wis; cure 2 consecutive saves."}],"description":"Dorus are the divs that whisper in the night, the foul inspiration that drifts upon fetid winds, the messengers of pretender gods. Wild hair whips around a doru's six twisting horns, while a flat nose, a fanged mouth, and red\n\nglowing eyes complete the terrifying image of this bodiless monstrosity. Dorus almost always fly, preferring to stay at heights that keep them at the eye level of those with whom they would have dealings. When not flying, dorus roll across the ground in a disturbing manner, horns bouncing and teeth clattering as the creatures cackle and cartwheel, terrifying children and shocking the faint of heart.\n\nThe least of the divs, dorus serve as messengers and servants of other divs and sometimes mortal spellcasters. While not strong combatants, dorus prefer to sow ruin in more subtle ways. They enjoy tainting mortals with exaggerated news and outright lies, trying to turn impressionable beings to waste and wickedness. Even if a doru fails to fully corrupt an intelligent being itself, it attempts to weaken the target's will, making the victim more pliable to future corruption and ruin.\n\nAll divs have some manner of esoteric flaw in their personalities; dorus are obsessed with secrets. These covetous fiends hoard secrets and legends like a miser hoards gold. This thirst for information causes the curious dorus to enter into ridiculous bargains to obtain hidden knowledge from those they believe hold tales of special interest or value, especially when such information has the potential to aid in the corruption of future souls. Such bargains are usually what seal dorus to servitude, whether their service be to other divs or to mortal spellcasters. Cunning creatures, dorus often act as double (and sometimes triple) agents, but they rarely maintain this complex series of lies and deceptions for long. Dorus abhor mortals, as all divs do, and find it difficult to remain obedient to such beings for more than a span of a few decades at most. Only the most precious and profane secrets have the potential to keep a doru faithful to a mortal master for more than a century.\n\nServing greater divs or mortal spellcasters, divs deliver messages, most directly plucked from secret sources. Dorus' spell-like abilities make them excellent spies, granting them the ability to infiltrate, eavesdrop while invisible, and charm their way out of perilous situations. Those serving mortals pride themselves on manipulating their masters into furthering the divs' own ends. Many evil spellcasters seeking profane power and ancient evil secrets seek to take dorus as familiars. A neutral evil spellcaster of at least 7th level who takes the Improved Familiar feat can select a doru as a familiar.","ecology":"","habitat_society":""},{"name":"Draugr","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"undead","subtypes":["water"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+2 armor, +2 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":2,"ref":1,"will":15,"dr":"5/bludgeoning or slashing","immunities":["undead traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"greataxe +5 (1d12+4/x3 plus nausea) or  slam +5 (1d10+4 plus nausea)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":10,"intelligence":8,"wisdom":10,"charisma":13,"baseatk":2,"cmb":5,"cmd":15,"feats":[{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":6},{"skill":"Stealth","value":6},{"skill":"Swim","value":11}],"languages":["Common (cannot speak)"],"environments":["any coastal"],"organizations":["solitary","crew (2-8)"],"treasure":"standard (greataxe, leather armor)","description_visual":"This barnacle-encrusted walking corpse looks like a zombie, but is dripping with water and gives off a nauseating stench.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Nausea","kind":"Su","details":"A creature that is damaged by a draugr must make a DC 12 Fortitude save or be nauseated for 1 round. The save DC is Charisma-based."}],"description":"Draugr smell of decay and the sea, and drip water wherever they go. These foul beings are usually created when humanoid creatures are lost at sea in regions haunted by evil spirits or necromantic effects. The corpses of these drowned sailors cling fiercely to unlife, attacking any living creatures that intrude upon them. Their attacks smear rancid flesh, rotting seaweed, and swaths of vermin on whatever they hit.\n\nIn the case of draugr who manifest when an entire ship sinks, these undead usually stay with the wreck of their ship. Some draugr may be found under the control of aquatic necromancers, while others may wander the seas as undead pirates aboard ghost ships.\n\nDRAUGR CAPTAIN (CR 3)\n\nDraugr captains have malevolent, burning red eyes. They may be more richly dressed than other draugr, though their clothes are always in a similar tattered condition.\n\nA draugr captain is a draugr with the advanced simple template. In addition to this, most draugr captains have additional class levels, usually as barbarians, fighters, or rogues. Draugr captains can also use obscuring mist as a spell-like ability (CL 5th, concentration +8) three times per day, and instead of causing nausea with a successful hit, they bestow 1 negative level on a hit. A draugr captain can even bestow a negative level via a weapon it wields, but if it gains multiple attacks with a weapon, it can only bestow 1 negative level per round in this manner.","ecology":"","habitat_society":""},{"name":"Dretch","cr":2,"xp":600,"alignment":"CE","size":"Small","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+3 natural, +1 size","hp":18,"hd":"2d10+7","hdvalue":2,"fort":5,"ref":0,"will":12,"dr":"5/cold iron or good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":20}],"melee":"2 claws +4 (1d4+1), bite +4 (1d4+1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"cause fear"},{"spell":"stinking cloud"},{"spell":"summon","details":"level 1, 1 dretch 35%"}]}],"strength":12,"dexterity":10,"constitution":14,"intelligence":5,"wisdom":11,"charisma":11,"baseatk":2,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Escape Artist","value":5},{"skill":"Perception","value":5},{"skill":"Stealth","value":9}],"languages":["Abyssal (cannot speak)","telepathy 100 ft. (limited to Abyssal-speaking targets)"],"environments":["any (Abyss)"],"organizations":["solitary","pair","gang (3-5)","crowd (6-12)","mob (13+)"],"treasure":"none","description_visual":"This creature's bloated frame shudders with each heaving step, yet despite its shape, the thing moves with surprising quickness.","group":"Demon","source":"PFRPG Bestiary","description":"Even the lowest demons of the Abyss are dangerous and filled with a driving need to spread ruin and dismay. The lowly dretch is as hideous and foul as it is cruel, even if it lacks the strength and power to realize its need to brutalize others in its native realm. The lot of the dretch's existence is to serve more powerful demons as victims, and only the lucky few survive long enough to evolve. The dretch is a favorite target for dabblers in Abyssal summonings to call forth. Relatively weak and easy to bully, dretches can often be pressured into long periods of servitude with only vague promises of the opportunity to vent their frustrations and anger on softer foes. Yet the prospective dretch-summoner would do well to remember that these demons are as craven and untrustworthy as they come. A dretch faced with a more powerful foe is only too eager to trade what it knows for its pitiful excuse for a life. Unlike most demons, a dretch's slovenly personality and disdain for prolonged physical labor rarely result in success. Advanced dretches are rare, but those who do find it within themselves to be more than they were at creation often become the pauper-kings of the Abyss, cruel and bitter in their rule over vermin, broken souls, mindless undead, and other dretches. Their empires are confined to abandoned stretches of sewers under backwater cities, unstable reaches of swampland avoided by more sensible minds, and other undesirable corners of the Abyss that even demons find uncomfortable or foul. Yet to the dretch lords, these realms are their empires, and they defend them with a pitiful tenacity. A dretch stands 4 ft. tall and weighs 180 pounds. Dretches typically form from the souls of slothful, evil mortals-yet it only takes a small fragment of a soul to trigger such a hideous birth. A single soul can often trigger the manifestation of a small army of dretches, and the sight of a horde of fresh-birthed dretches pulling free from the heaving protomatter of the Abyss is a nauseating and terrifying one indeed.","ecology":"","habitat_society":""},{"name":"Dweomercat Cub","cr":2,"xp":600,"alignment":"CN","size":"Tiny","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":16,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +1 natural, +2 size","hp":16,"hd":"3d10","hdvalue":3,"fort":3,"ref":5,"will":15,"dr":"5/magic","sr":14,"speed":[{"type":"land","speed":20}],"melee":"2 claws +7 (1d2-1), bite +7 (1d3-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"dweomer leap"},{"type":"pounce"},{"type":"rake","details":"2 claws +6, 1d2-1"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"1/week","spells":[{"spell":"dimension door","details":"self only"}]}],"strength":9,"dexterity":15,"constitution":10,"intelligence":9,"wisdom":12,"charisma":14,"baseatk":3,"cmb":21,"cmb_special":"+4 vs. grapple","cmd":39,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":3},{"skill":"Knowledge (arcana)","value":0},{"skill":"Perception","value":5},{"skill":"Stealth","value":4}],"languages":["Common","Sylvan"],"environments":["any forests"],"organizations":["solitary","ambush (1-3 dweomercats and 2-12 dweomercat cubs)"],"treasure":"standard","description_visual":"Its coat shining vividly, this majestic tiger looks exotic and otherworldly. It gazes with piercing yellow eyes and stands calmly, as though fearless.","source":"AP 36","special_abilities":[{"type":"Dweomer Leap","kind":"Su","details":"When a dweomercat is targeted by a spell or within the area of effect of a spell, it can, as a swift action, choose to teleport to a square adjacent to the spell's caster, effectively appearing mid-leap and aimed toward the caster. This ability takes effect regardless of whether or not the spell overcomes the dweomercat's spell resistance. If it chooses, the dweomercat can immediately make a full attack against the spell's caster as though pouncing. Using this ability doesn't provoke an attack of opportunity. If there is no safe space adjacent to the caster-or if the dweomercat chooses-the dweomercat can forgo using this ability."}],"description":"Powerful and regal, dweomercats stalk the First World, preying upon lesser creatures, but more voraciously hunting new and ever stranger sources of magic. Beings as much composed of sculpted arcane eddies as of flesh and blood, these capricious felines flourish along the intangible ley lines of their home realm, drinking in its weird powers as a plant thrives on light. Yet even more potent than their thirst for magic and the euphoria they draw from being in proximity to the reshaping of reality is dweomercats' racial curiosity, which leads them endlessly across the First World-and often beyond. The average adult dweomercat is about 4 ft. tall and 7 ft. long, weighing over 250 pounds, while their cubs are approximately 1 foot tall and weigh no more than 15 pounds. Ecology A newly born dweomercat cub is connected to its homeland by only a thin tether of fey magic, and can only tap into its true potential during the instant a spell is cast upon it. The burst of magical energy brought forth by a freshly cast spell momentarily intensifies the bond between the First World and the dweomercat. This link manifests itself clumsily as a sort of sudden teleportation that heaves the fey cat through space and time toward the source of the spell, fueled by the magnetic reaction between the dweomercat and the magic's origin. A dweomercat grows not by the passage of time, but through direct exposure to fey magic. Thus, a dweomercat cub on the Material Plane is stunted developmentally. Though it ages and gains experience and practical wisdom anywhere, only by spending several lifetimes on the First World can the cub reach adulthood. Once it has reached this stage, however, a fully grown dweomercat may freely travel between its native land and the Material Plane without adverse effects. Habitat & Society In the First World, dweomercats travel in packs while hunting. Beyond this predatory advantage, however, they have little use for organized society, as the evershifting nature of their homeland impedes it anyway. Dweomercats that are born on or come to be stranded on the Material Plane are often forced to live on their own. Cut off from the direct magical eddies of the First World, dweomercat cubs prove unable to grow into adults. While they might become slightly stronger and more learned, they never reach the size and prowess of those constantly subjected to the magic of their homeland. Were a dweomercat cub to return to the First World, it would eventually grow into a normal dweomercat, but only over the course of numerous humanoid lifespans. Those dweomercats marooned on the Material Plane seek out areas of great age, changeability, and magical potency; lands most like the First World. Sometimes this means not a specific place, but rather a period spent journeying with a mortal spellcaster. While an adult dweomercat would scoff at the idea of following a humanoid's orders, adolescents see the benefit of journeying alongside an intelligent creature native to the alien world. Should a dweomercat cub find a magic-user reckless or whimsical enough to keep its attention, it might join the caster as a familiar, gaining a measure of constant magical exposure from the intangible connection inherent in such a mystical relationship. Dweomercat Cubs as Familiars Attracted to flashy displays of magic and the strange powers inherent in a bond between a magic-user and her familiar, a dweomercat cub that's wandered from the First World might find its taste for magic and adventure satisfied in the service of a particularly whimsical or ostentatious arcane spellcaster. A spellcaster with the Improved Familiar feat can acquire a chaotic neutral dweomercat cub at 7th level or higher. Should the spellcaster settle into a life of research and predictability for a span of months, the dweomercat cub familiar might take to wandering off and, eventually, might not return-deliberately severing the master-familiar bond and freeing the spellcaster to summon a new familiar.","ecology":"A newly born dweomercat cub is connected to its homeland by only a thin tether of fey magic, and can only tap into its true potential during the instant a spell is cast upon it. The burst of magical energy brought forth by a freshly cast spell momentarily intensifies the bond between the First World and the dweomercat. This link manifests itself clumsily as a sort of sudden teleportation that heaves the fey cat through space and time toward the source of the spell, fueled by the magnetic reaction between the dweomercat and the magic's origin. A dweomercat grows not by the passage of time, but through direct exposure to fey magic. Thus, a dweomercat cub on the Material Plane is stunted developmentally. Though it ages and gains experience and practical wisdom anywhere, only by spending several lifetimes on the First World can the cub reach adulthood. Once it has reached this stage, however, a fully grown dweomercat may freely travel between its native land and the Material Plane without adverse effects.","habitat_society":"In the First World, dweomercats travel in packs while hunting. Beyond this predatory advantage, however, they have little use for organized society, as the evershifting nature of their homeland impedes it anyway. Dweomercats that are born on or come to be stranded on the Material Plane are often forced to live on their own. Cut off from the direct magical eddies of the First World, dweomercat cubs prove unable to grow into adults. While they might become slightly stronger and more learned, they never reach the size and prowess of those constantly subjected to the magic of their homeland. Were a dweomercat cub to return to the First World, it would eventually grow into a normal dweomercat, but only over the course of numerous humanoid lifespans. Those dweomercats marooned on the Material Plane seek out areas of great age, changeability, and magical potency; lands most like the First World. Sometimes this means not a specific place, but rather a period spent journeying with a mortal spellcaster. While an adult dweomercat would scoff at the idea of following a humanoid's orders, adolescents see the benefit of journeying alongside an intelligent creature native to the alien world. Should a dweomercat cub find a magic-user reckless or whimsical enough to keep its attention, it might join the caster as a familiar, gaining a measure of constant magical exposure from the intangible connection inherent in such a mystical relationship. Dweomercat Cubs as Familiars Attracted to flashy displays of magic and the strange powers inherent in a bond between a magic-user and her familiar, a dweomercat cub that's wandered from the First World might find its taste for magic and adventure satisfied in the service of a particularly whimsical or ostentatious arcane spellcaster. A spellcaster with the Improved Familiar feat can acquire a chaotic neutral dweomercat cub at 7th level or higher. Should the spellcaster settle into a life of research and predictability for a span of months, the dweomercat cub familiar might take to wandering off and, eventually, might not return-deliberately severing the master-familiar bond and freeing the spellcaster to summon a new familiar."},{"name":"Eagle Knight","cr":2,"xp":600,"race":"Human","classes":[{"class":"fighter","level":3}],"alignment":"LG","size":"Medium","type":"humanoid","subtypes":["human"],"init":3,"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+6 armor, +3 Dex","hp":24,"hd":"3d10+3","hdvalue":3,"fort":4,"ref":4,"will":2,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk greatsword +6 (2d6+1/19-20)","ranged":"mwk composite longbow +7 (1d8+1/x3)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":17,"constitution":12,"intelligence":10,"wisdom":8,"charisma":14,"baseatk":3,"cmb":4,"cmd":17,"feats":[{"feat":"Cleave"},{"feat":"Deadly Aim"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Knowledge (history)","value":1},{"skill":"Knowledge (local)","value":1},{"skill":"Perception","value":2},{"skill":"Sense Motive","value":2},{"skill":"Stealth","value":4},{"skill":"Survival","value":3}],"languages":["Common"],"sq":[{"type":"armor training","details":"1"}],"environments":["any land (Andoran and surrounding nations)"],"organizations":["solitary","pair","team (3-6)"],"treasure":"none","description_visual":"Golden eagles shine proudly on the steel armor of this blue-uniformed soldier.","source":"Andoran Birthplace Of Freedom","description":"Eagle Knights are the public face of Andoran in the eyes of surrounding nations-an army of citizen-soldiers who rose up to defend the hard-won freedoms of the Andoren people. The Eagle Knights serve at the forefront of their nation's armed forces, acting as scouts in dangerous regions and enemy territory, elite troops for the most perilous missions, officers for militias, and advisors to communities threatened by bandits, foreign raids, or dangerous wildlife. Eagle Knights put their lives on the line on a regular basis, and that risk earns them the respect of their fellow citizens.\n\nHowever, the war Eagle Knights wage isn't merely one of military combat. In a world dominated by monarchy and despotism, the citizen-soldiers must also fight on the vanguard of an ideological army, championing the strange notion that the ordinary citizens of a nation have both the right and responsibility to govern themselves. The Eagle Knights hold faith that the common folk are more than capable of holding a large nation together without being crushed beneath the weight of bureaucracy or dissolving into factional, sectional, and ideological squabbling that could hurl the nation into anarchy in the face of a crisis.\n\nAmong the Eagle Knights, the members of the Steel Falcons faction serve as Andoran's armed ambassadors to the world at large. While the larger part of the Eagle Knights is concerned with the nation's safety and order, the Steel Falcons travel abroad to bring awareness of the history and culture of Andoran to other lands and to spread the gospel of liberty. They travel not as seditionists (unless they are subverting tyranny), but rather as emissaries sharing the national narrative that makes Andoran unique among the nations. They are also trained listeners, culling important intelligence from information commonly available in the foreign lands they roam, returning to Andoran with invaluable details about attitudes and activities abroad.","ecology":"","habitat_society":"","gear":"mwk breastplate, mwk greatsword, mwk composite longbow with 20 arrows, wooden holy symbol, backpack"},{"name":"Electric Eel","cr":2,"xp":600,"alignment":"N","size":"Small","type":"animal","init":6,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":17,"hd":"2d8+8","hdvalue":2,"fort":7,"ref":5,"will":0,"resists":[{"type":"electricity","value":10}],"speed":[{"type":"land","speed":5},{"type":"swim","speed":30}],"melee":"bite +3 (1d6+1) and tail -2 touch (1d6 electricity)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":14,"constitution":19,"intelligence":1,"wisdom":10,"charisma":6,"baseatk":1,"cmb":1,"cmd":13,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Escape Artist","value":10},{"skill":"Perception","value":4},{"skill":"Stealth","value":10},{"skill":"Swim","value":9}],"environments":["warm water (freshwater)"],"organizations":["solitary"],"treasure":"none","description_visual":"This six-foot-long, snake-like fish moves slowly. A strange popping and snapping sound occasionally emits from the creature's body.","group":"Eel","source":"PFRPG Bestiary","special_abilities":[{"type":"Electricity","kind":"Ex","details":"An electric eel can produce a powerful jolt of electricity from its tail, delivering the jolt with a successful touch attack. On a critical hit, the creature struck must make a DC 15 Fortitude save or be stunned for 1d4 rounds. The save DC is Constitution-based."}],"description":"The electric eel is a curious fish that breathes air instead of water, yet certainly its most unusual characteristic is its ability to generate powerful jolts of electricity. An electric eel is 6 ft. long and weighs 45 pounds. Electric Eel Animal Companion Starting Statistics: Size Small; Speed 5 ft., swim 30 ft.; Attack bite (1d6); Ability Scores Str 12, Dex 14, Con 18, Int 1, Wis 10, Cha 6; Special Qualities amphibious, low-light vision, electricity resistance 5. 4th-Level Advancement: AC +2 natural armor; Ability Scores Dex +2, Con +2; Special Qualities electricity (1d6), electricity resistance 10.","ecology":"","habitat_society":""},{"name":"Erinat Gremlin","cr":2,"xp":600,"alignment":"CE","size":"Tiny","type":"fey","init":3,"senses":[{"type":"low-light vision"}],"auras":["discordant (20 ft.)"],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 size","hp":19,"hd":"3d6+9","hdvalue":3,"fort":3,"ref":6,"will":2,"dr":"5/cold iron","sr":13,"speed":[{"type":"land","speed":30}],"melee":"spiked chain +6 (1d4+3)","space":"2-1/2 ft.","reach":"0 ft. (5 ft. with spiked chain)","special_attacks":[{"type":"lashing chains"},{"type":"malicious mischief"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"alter self","details":"Small humanoid child only"},{"spell":"ghost sound"}]},{"frequency":"1/day","spells":[{"spell":"lesser confusion"},{"spell":"murderous command"},{"spell":"rage"}]}],"strength":14,"dexterity":16,"constitution":15,"intelligence":8,"wisdom":9,"charisma":14,"baseatk":1,"cmb":2,"cmd":14,"feats":[{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":8},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":13},{"skill":"Stealth","value":20}],"languages":["Aklo","Common","Undercommon"],"environments":["any underground","any urban"],"organizations":["solitary","pair","mob (3-8)"],"treasure":"standard (spiked chain)","description_visual":"The pockets of this urchin are stuffed with worthless objects.","group":"Gremlin","source":"Andoran Birthplace Of Freedom","special_abilities":[{"type":"Discordant Aura","kind":"Su","details":"An erinat radiates an aura that imparts both gullibility and susceptibility to mental influence. Creatures within a 20-foot radius take a -2 penalty on saves against compulsion effects, and Bluff checks attempted against such creatures gain a +5 bonus. This bonus also applies on opposed Charisma checks against a charmed creature within the aura."},{"type":"Lashing Chains","kind":"Ex","details":"Erinats have 5-foot reach when attacking on their turn with their spiked chains, though they don't threaten adjacent squares when it isn't their turn."},{"type":"Malicious Mischief","kind":"Su","details":"A pair of erinats working together for 1 round can present an item and compel a creature to take it. This functions as beguiling gift (DC 13), but rather than using the item in the appropriate fashion, the recipient is compelled to use the item to attack a random non-gremlin creature within 30 ft., even if the recipient must use the item as an improvised weapon. Additionally, a group of six erinats working together over the course of 1 hour can create an effect identical to malicious spite (DC 16) on any living creature. This effect functions at CL 6th, and the target creature must be either willing or helpless."}],"description":"Erinat gremlins are obsessed with conflict and discord. They love nothing more than starting fights-the more inane and pointless the struggle, the better. Erinat gremlins typically use alter self to take the appearance of unfed, unwashed humanoid children as appropriate to their surroundings, allowing the gremlins to move freely through settlements (and accuse anyone who attempts to stop their malicious conduct of trying to kidnap them). Erinats don't care who wins the fights they start; they simply wish to be entertained by the largest brawls they can arrange. The mischievous gremlins delight in creating chaos, and are prone to making outrageous claims in the hope of sparking riots, aided by forcing bystanders to attack each other with random, often ridiculous objects.","ecology":"","habitat_society":""},{"name":"Executioner's Hood","cr":2,"xp":600,"alignment":"N","size":"Tiny","type":"aberration","init":1,"senses":[{"type":"blindsense","modifier":"10 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":16,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+1 Dex, +3 natural, +2 size","hp":11,"hd":"2d8+2","hdvalue":2,"fort":1,"ref":1,"will":4,"defensive_abilities":["amorphous"],"immunities":["sleep effects"],"weaknesses":["light sensitivity","susceptible to alcohol"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":5}],"melee":"slam +3 (1d4 plus grab)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"constrict","details":"1d4"},{"type":"engulfing drop"},{"type":"strangle"}],"strength":10,"dexterity":12,"constitution":12,"intelligence":3,"wisdom":13,"charisma":9,"baseatk":1,"cmb":0,"cmb_special":"+4 vs. grapple","cmd":10,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":8},{"skill":"Stealth","value":13}],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature resembles an executioner's hood constructed of blackish-gray leather. Two hollow eye holes are present in its form.","group":"Lurking Ray","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Engulfing Drop","kind":"Ex","details":"Though it is a Tiny monster, the hood can drop onto the head of a Medium or smaller creature and make a slam attack as a standard action. If the hood's attack succeeds, it can immediately attempt a grapple check against the target, and if successful, the executioner's hood can constrict."},{"type":"Strangle","kind":"Ex","details":"A grappling executioner's hood entirely covers its opponent's head with an airtight grip. A creature that is grappled by the hood cannot speak or cast spells with verbal components and must hold its breath (see Suffocation), unless it doesn't speak or breathe through its head. Any attacks against the hood deal half damage to the hood and the other half to the creature that it's strangling."},{"type":"Susceptible to Alcohol","kind":"Ex","details":"Strong alcohol harms the hood. Every quart poured on it deals 1 point of damage. Four quarts of alcohol incapacitates it and forces it to release a grappled target."}],"description":"These young rays are shaped roughly like hoods (hence their name), and drag themselves awkwardly about with their thin tentacles. Once an executioner's hood finds a suitable hunting ground, usually a cavern or dungeon room, it hauls itself up to a high perch and hangs there, disguising itself as an irregular stone formation or a strange bit of masonry on a dungeon wall. When suitable prey walks beneath it, the young lurking ray drops, attempting to engulf the creature's head and suffocate it, after which the ray can slowly dissolve the meat at its leisure. Executioner's hoods are hatched from eggs laid by trappers. They stay with the mother for a month, then leave to hunt for themselves.","ecology":"","habitat_society":""},{"name":"Faerie Dragon","cr":2,"xp":600,"alignment":"CG","size":"Tiny","type":"dragon","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+3 Dex, +1 dodge, +2 natural, +2 size","hp":22,"hd":"3d12+3","hdvalue":3,"fort":4,"ref":6,"will":5,"immunities":["paralysis","sleep"],"sr":13,"speed":[{"type":"land","speed":10},{"type":"fly","speed":60,"maneuverability":"perfect"},{"type":"swim","speed":30}],"melee":"bite +4 (1d3-1)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"breath weapon","details":"5-ft. cone, euphoria, Fort DC 12 negates, usable every 1d4 rounds"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"greater invisibility","details":"self only"}]}],"spellsknown_caster_level":3,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"grease"},{"spell":"silent image"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"open/close"}]}],"strength":9,"dexterity":17,"constitution":13,"intelligence":16,"wisdom":14,"charisma":16,"baseatk":3,"cmb":4,"cmd":14,"cmd_special":"+4 vs. trip","feats":[{"feat":"Acrobatic"},{"feat":"Dodge"}],"skills":[{"skill":"Acrobatics","value":8,"special":"+0 when jumping"},{"skill":"Bluff","value":9},{"skill":"Diplomacy","value":9},{"skill":"Fly","value":23},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":17},{"skill":"Swim","value":17},{"skill":"Use Magic Device","value":9}],"languages":["Common","Draconic","Elven","Sylvan","telepathy 100 ft."],"environments":["temperate forests","warm forests"],"organizations":["solitary","clan (2-8)"],"treasure":"standard","description_visual":"A pair of brightly colored butterf ly wings sprouts from the back of this miniature dragon.","group":"Dragon","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"5-foot cone, euphoria for 1d6 rounds, DC 12 Fortitude negates. Creatures affected by euphoria are staggered, sickened, and immune to fear effects for the duration. A faerie dragon can use this breath weapon once every 1d4 rounds. The save DC is Constitution-based. Spells A faerie dragon casts spells as a 3rd-level sorcerer."}],"description":"Related to pseudodragons, faerie dragons are whimsical, playful pranksters that spend most of their time either relaxing in cool forest glades or engaged in some sort of prank. Although such mischief is usually spontaneous, some faerie dragons have been known to spend months\n\nor even years in preparation of one truly spectacular joke. Travelers making their way through lands known to be inhabited by these good-natured-but sometimes annoying-tricksters are advised to keep up their guard lest they face all manner of creative annoyances (horses painted with berry juice, squirrels placed inside bedrolls, and clothing decorating high branches being a few examples).\n\nUnlike true dragons, faerie dragons don't grow larger with age, but their scales do change color, starting with red and moving through the rainbow to reach dark violet at old age. Faerie dragons grow in power as spellcasters as they age (typically gaining levels in sorcerer), learning more powerful spells to complement their innate abilities. The spells of faerie dragons tend to focus on tools that can be used to create or enhance pranks, and illusion and enchantment spells are particularly popular.\n\nFaerie dragons avoid combat unless there is no other option. If forced to fight, faerie dragons attempt to confound enemies rather than kill them, using both spells and breath weapon to weaken and scatter foes before fleeing. The only exception to this is when a faerie dragon's clan or allies are in danger. As capricious as these tiny dragons can be, many prove quick to bond with goodly creatures, especially fey and others they find interesting or hilarious-adventurers often fall into this latter camp, particularly those most outraged by a faerie dragon's tricks.\n\nFaerie dragons sometimes ally with spellcasters, serving as curious, occasionally reckless, but always true familiars. An arcane spellcaster of at least 7th level with an alignment within 1 step of chaotic good who has the Improved Familiar feat may select a faerie dragon as a familiar.","ecology":"","habitat_society":""},{"name":"Fleshdreg Swarm","cr":2,"xp":600,"alignment":"NE","size":"Tiny","type":"aberration","subtypes":["swarm"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"sin-scent"}],"ac":15,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+1 Dex, +2 natural, +2 size","hp":19,"hd":"3d8+6","hdvalue":3,"fort":3,"ref":4,"will":3,"defensive_abilities":["swarm traits"],"immunities":["mind-affecting effects"],"sr":13,"speed":[{"type":"land","speed":30},{"type":"climb","speed":10}],"melee":"swarm (1d6 plus distraction)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 13"}],"strength":2,"dexterity":13,"constitution":15,"intelligence":2,"wisdom":11,"charisma":2,"baseatk":2,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Perception","value":5},{"skill":"Stealth","value":13}],"sq":[{"type":"arcane bite"}],"environments":["any ruins"],"organizations":["solitary","pair","infestation (3-5)"],"treasure":"none","description_visual":"Hundreds of wads of squirming flesh with flailing appendages move together in a cluster of teeth and claws.","group":"Fleshdreg","source":"AP 61","special_abilities":[{"type":"Arcane Bite","kind":"Su","details":"A fleshdreg swarm's swarm damage is considered magical for the purposes of overcoming damage reduction."},{"type":"Sin-Scent","kind":"Su","details":"Fleshdreg swarms have scent against creatures whose nature reflects the fleshdreg swarm's related sin. For example, a wrathful fleshdreg swarm can scent creatures using rage effects. The GM should adjudicate what creatures a particular fleshdreg swarm can scent."}],"description":"Fleshdreg swarms form from scraps and leftovers of malformed fleshdregs and incomplete sinspawn. These foul, misshapen creatures pour out of runewells by the hundreds, seeking sinful flesh to destroy. Little more than pests, these swarms attack indiscriminately. Some malfunctioning runewells and other fleshvats produce nothing more these days than swarm upon swarm of these pests.","ecology":"","habitat_society":""},{"name":"Flood Troll","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["giant"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":10,"ac_mods":"+4 Dex","hp":22,"hd":"3d8+9","hdvalue":3,"hp_mods":["rain regeneration 5 (acid or fire)"],"fort":6,"ref":5,"will":1,"defensive_abilities":["absorbent hide"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":10}],"melee":"2 claws +6 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"}],"strength":15,"dexterity":18,"constitution":16,"intelligence":8,"wisdom":11,"charisma":7,"baseatk":2,"cmb":4,"cmd":18,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":5},{"skill":"Swim","value":11}],"languages":["Giant"],"sq":[{"type":"hold breath"},{"type":"oversized limbs"}],"environments":["temperate rivers","temperate swamps"],"organizations":["solitary","pair (usually twins)"],"treasure":"standard","description_visual":"This tall, gangly giant has a thick hide of mottled blue; protruding yellowed canines; narrow slits for eyes; and large, powerful hands that end in wicked claws.","group":"Troll","source":"AP 91","special_abilities":[{"type":"Absorbent Hide","kind":"Ex","details":"A flood troll's flesh is highly resilient to the stresses of long dry periods. A flood troll who has gone without touching flowing water for at least 24 hours gains a +2 natural armor bonus to AC. A flood troll who has touched water within the last 24 hours gains cold resistance 5 instead."},{"type":"Oversized Limbs","kind":"Ex","details":"A flood troll's hands are larger than its body would suggest. Flood trolls can wield Large weapons without penalty."},{"type":"Rain Regeneration","kind":"Ex","details":"A flood troll's regeneration functions as long as the flood troll is touching flowing water or precipitation. Even a slight drizzle is enough to activate the flood troll's regeneration. However, any acid or fire damage dealt to the flood troll suspends its next round of regeneration."}],"description":"Flood trolls are the mutated runts of scrag broods, cast out by their mothers and destined to haunt the lonely valleys and river basins beneath Avistan's frosty peaks. They lurk amid the craggy hills of Belkzen, Varisia, and other wildlands of northern Avistan, and serve as a menace to orc raiders and human adventurers alike. While smaller and less organized than true scrags, flood trolls' solitary nature and desperation for food often drives them to commit atrocities upon\n\nunsuspecting humanoid populations-atrocities that almost invariably end with the flood trolls' eventual capture and execution.\n\nFlood trolls average 7-1/2 ft. tall and weigh 250 pounds.\n\nEcology\n\nFlood trolls are not actual trolls in the truest sense of the word. Although flood trolls—like their scrag parents- are distantly related to mountain trolls, the species are distinct. Most humanoid societies, however, are content to simply refer to both scrags and trolls using the umbrella term \"troll,\" linking the species because of overlapping myths and their similar regenerative abilities.\n\nScrag mothers birth anywhere from two to six younglings in a single brood, and every brood has a small chance of including what the scrags call an aruk-taii-\"half-scrag\" in the Giant tongue-known to many civilized peoples as a flood troll. Scrags with larger broods have a higher chance of producing flood trolls among their young. These runts are invariably smaller and more frail than true scrag younglings, and their growth rate is significantly slower than their non-mutated kin. This makes them undesirable to their scrag mothers and more likely to be eaten by their stronger siblings. Those flood trolls who aren't simply abandoned to the wilds by their mothers are raised as lesser beings, and live in the shadows of their scrag brothers and sisters. Most flood trolls flee their aggressive broodmates before coming of age, preferring to fend for themselves in the terrors of the wilderness rather than deal with their cruel, savage family members.\n\nThe mutation that results in a flood troll stymies many of the racial abilities typical to scrags. For one, flood trolls lack the amphibious special quality, making them much less suited to hunting underwater. Unfortunately for them, flood trolls still rely on exposure to water to enable their regenerative properties, meaning they must dwell near water but never wholly within it. Not just any water will do, either-only water that is continually refreshed with minerals and oxygen can regenerate flood trolls. Stagnant or relatively still waters such as small lakes and ponds cannot provide the nutrients flood troll regeneration requires, which means these monsters tend to stay near active waterways and areas with high precipitation where they can find the flowing water and rainfall that helps them to survive.\n\nThe mutation that results in a flood troll also affects the creature's reproductive organs, rendering it sterile. Because they cannot reproduce, flood trolls rarely seek out mates or even partners to aid in the hunt. Instead, they lead solitary existences steeped in ire for all living things; they are born amid hatred and rejection, and expect to die the same way.\n\nIn rare instances, a scrag mother may produce flood troll twins. In keeping with their primitive superstitions, scrags believe the arrival of two flood trolls is a dire omen that signals the coming of storms and floods, and cannot be dealt with by simply tossing the younglings away. Instead, the scrags believe, in order to appease the dread deities that they believe control the weather and the flow of rivers into their aquatic homes, the scrags must raise aruk-taii twins, aruk-taikii, as they would raise their true scrag offspring. The scrag mother-along with the other female scrags in her group-raises and nurtures the twins as best as she is able, albeit with grudging reluctance. In fact, the association between aruk-taikii and inclement weather in these old scrag myths is what originally inspired human adventurers to name the beasts flood trolls.\n\nHabitat & Society\n\nFlood trolls are monstrous nomads-wandering hunters who follow the herds of game and pay close attention to humanoids' travel patterns as they journey between the distant settlements of northern Avistan. They are cunning by necessity, since they are smaller than their brethren and must often surprise their prey to earn their meals. While not afraid to pounce on their victims once they can catch them, most flood trolls prefer to use stealth tactics and crude traps to put prospective victims in hazardous situations before attempting an ambush.\n\nScrag mothers eject their flood troll spawn from the brood as soon as the youngling's hormonal mutation makes itself known, which typically occurs a couple of years after the brood is born. Abandoned aruk-taii younglings survive in the wilds by sticking close to a river or freshwater source, and those who fail to find fresh water typically fall prey to wolves or other predators. Solitary by circumstance, flood trolls are seen in pairs only rarely, and usually because the two are twins. Because flood troll twins are pampered and treated with care by their scrag mother (rather than being abused and ostracized), these specimens tend to be more intelligent and creative than their solitary kin. Some flood trolls even learn how to wield arms or poison daggers; woe betide anyone who feels the sting of an aruk-taii rogue's dirk-if not for the blade, then for the savage claws that come afterward.\n\nBecause they can survive in arid environments for longer periods, flood trolls are much more common in Belkzen than their scrag forebears. The orcs of Belkzen claim that flood trolls wander over the Mindspin and Kodar mountain\n\nranges, fleeing their scrag families in the Mushfens and Varisia's other wetlands. In the frigid Lands of the Linnorm Kings and Irrisen, scrags dwelling along the coast of the Arcadian Ocean and in Glacier Lake drive their flood troll offspring south along the Marblef low River or east toward the Gullik River. While they are most commonly encountered in Avistan, flood trolls may be found around the world, wherever scrags carry the aruk-taii mutation, though their physical features vary somewhat depending on where they originate. The Zenj tribes of the Mwangi Expanse speak of blue-skinned, humanoid horrors-jeburo in the Polyglot tongue-that stalk the jungle's riverbeds during the dry season and boldly attack villages as the storm season approaches. A number of these flood trolls make their way into the Sodden Lands. Never lacking for the rain that allows for their regeneration, these flood trolls terrorize the few remaining enclaves of humanity in that drenched land.","ecology":"Flood trolls are not actual trolls in the truest sense of the word. Although flood trolls—like their scrag parents- are distantly related to mountain trolls, the species are distinct. Most humanoid societies, however, are content to simply refer to both scrags and trolls using the umbrella term \"troll,\" linking the species because of overlapping myths and their similar regenerative abilities.\n\nScrag mothers birth anywhere from two to six younglings in a single brood, and every brood has a small chance of including what the scrags call an aruk-taii-\"half-scrag\" in the Giant tongue-known to many civilized peoples as a flood troll. Scrags with larger broods have a higher chance of producing flood trolls among their young. These runts are invariably smaller and more frail than true scrag younglings, and their growth rate is significantly slower than their non-mutated kin. This makes them undesirable to their scrag mothers and more likely to be eaten by their stronger siblings. Those flood trolls who aren't simply abandoned to the wilds by their mothers are raised as lesser beings, and live in the shadows of their scrag brothers and sisters. Most flood trolls flee their aggressive broodmates before coming of age, preferring to fend for themselves in the terrors of the wilderness rather than deal with their cruel, savage family members.\n\nThe mutation that results in a flood troll stymies many of the racial abilities typical to scrags. For one, flood trolls lack the amphibious special quality, making them much less suited to hunting underwater. Unfortunately for them, flood trolls still rely on exposure to water to enable their regenerative properties, meaning they must dwell near water but never wholly within it. Not just any water will do, either-only water that is continually refreshed with minerals and oxygen can regenerate flood trolls. Stagnant or relatively still waters such as small lakes and ponds cannot provide the nutrients flood troll regeneration requires, which means these monsters tend to stay near active waterways and areas with high precipitation where they can find the flowing water and rainfall that helps them to survive.\n\nThe mutation that results in a flood troll also affects the creature's reproductive organs, rendering it sterile. Because they cannot reproduce, flood trolls rarely seek out mates or even partners to aid in the hunt. Instead, they lead solitary existences steeped in ire for all living things; they are born amid hatred and rejection, and expect to die the same way.\n\nIn rare instances, a scrag mother may produce flood troll twins. In keeping with their primitive superstitions, scrags believe the arrival of two flood trolls is a dire omen that signals the coming of storms and floods, and cannot be dealt with by simply tossing the younglings away. Instead, the scrags believe, in order to appease the dread deities that they believe control the weather and the flow of rivers into their aquatic homes, the scrags must raise aruk-taii twins, aruk-taikii, as they would raise their true scrag offspring. The scrag mother-along with the other female scrags in her group-raises and nurtures the twins as best as she is able, albeit with grudging reluctance. In fact, the association between aruk-taikii and inclement weather in these old scrag myths is what originally inspired human adventurers to name the beasts flood trolls.","habitat_society":"Flood trolls are monstrous nomads-wandering hunters who follow the herds of game and pay close attention to humanoids' travel patterns as they journey between the distant settlements of northern Avistan. They are cunning by necessity, since they are smaller than their brethren and must often surprise their prey to earn their meals. While not afraid to pounce on their victims once they can catch them, most flood trolls prefer to use stealth tactics and crude traps to put prospective victims in hazardous situations before attempting an ambush.\n\nScrag mothers eject their flood troll spawn from the brood as soon as the youngling's hormonal mutation makes itself known, which typically occurs a couple of years after the brood is born. Abandoned aruk-taii younglings survive in the wilds by sticking close to a river or freshwater source, and those who fail to find fresh water typically fall prey to wolves or other predators. Solitary by circumstance, flood trolls are seen in pairs only rarely, and usually because the two are twins. Because flood troll twins are pampered and treated with care by their scrag mother (rather than being abused and ostracized), these specimens tend to be more intelligent and creative than their solitary kin. Some flood trolls even learn how to wield arms or poison daggers; woe betide anyone who feels the sting of an aruk-taii rogue's dirk-if not for the blade, then for the savage claws that come afterward.\n\nBecause they can survive in arid environments for longer periods, flood trolls are much more common in Belkzen than their scrag forebears. The orcs of Belkzen claim that flood trolls wander over the Mindspin and Kodar mountain\n\nranges, fleeing their scrag families in the Mushfens and Varisia's other wetlands. In the frigid Lands of the Linnorm Kings and Irrisen, scrags dwelling along the coast of the Arcadian Ocean and in Glacier Lake drive their flood troll offspring south along the Marblef low River or east toward the Gullik River. While they are most commonly encountered in Avistan, flood trolls may be found around the world, wherever scrags carry the aruk-taii mutation, though their physical features vary somewhat depending on where they originate. The Zenj tribes of the Mwangi Expanse speak of blue-skinned, humanoid horrors-jeburo in the Polyglot tongue-that stalk the jungle's riverbeds during the dry season and boldly attack villages as the storm season approaches. A number of these flood trolls make their way into the Sodden Lands. Never lacking for the rain that allows for their regeneration, these flood trolls terrorize the few remaining enclaves of humanity in that drenched land."},{"name":"Foo Dog","cr":2,"xp":600,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["augmented animal","good","extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":17,"hd":"2d10+6","hdvalue":2,"fort":6,"ref":5,"will":3,"defensive_abilities":["paired protectors","stony defense 2/day"],"dr":"5/bludgeoning","immunities":["poison","disease","paralysis","sleep"],"speed":[{"type":"land","speed":40}],"melee":"bite +4 (1d6+4 plus trip)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":15,"constitution":17,"intelligence":6,"wisdom":12,"charisma":6,"baseatk":1,"cmb":4,"cmd":16,"cmd_special":"+4 vs. trip","feats":[{"feat":"Iron Will","type":"bonus"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":6,"special":"+14 when jumping"},{"skill":"Perception","value":8},{"skill":"Survival","value":1,"special":"+5 scent tracking"}],"languages":["Celestial","Common"],"sq":[{"type":"freeze"}],"environments":["any (Nirvana)"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"There can be no mistaking this animal-like creature for a mere beast, for its face has an almost supernaturally human look to it.","group":"Foo Creature","source":"PFRPG Bestiary 3","description":"Foo creatures are benevolent guardian spirits that hail originally from the Outer Plane of Nirvana, where they spend their days cavorting in the idyllic wilds or aiding that realm's inhabitants, particularly the agathions, in their work. Yet while they come from Nirvana, foo creatures are often encountered on the Material Plane as well, for they are favorite conjurations of many cultures and religions.\n\nCountless species of foo creatures exist-for if an animal dwells upon the Material Plane, it is certain that somewhere in the vast wilds of Nirvana its spiritual double frolics and plays. Nonetheless, certain foo creatures are more common than others, and the most often encountered of all are dogs and lions.\n\nA foo creature can be called to the Material Plane for any reason a conjurer can imagine-these monsters are generally much more intelligent than their mundane counterparts, and can not only follow complex orders but can speak and converse as well. Typically, a foo creature is contacted to serve for a time as a guardian-by adopting its statue form using its freeze ability, a foo creature can appear as little more than an ornate decoration astride the facade of a building or standing guard over a fountain in a city plaza. They are not as often called upon to serve as soldiers in armies, for foo creatures detest war. They generally dislike serving as mounts as well, although for particularly pious and kindly folk, they have been known to make exceptions.","ecology":"","habitat_society":""},{"name":"Forlarren","cr":2,"xp":600,"alignment":"NE","size":"Medium","type":"fey","init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":18,"hd":"4d6+4","hdvalue":4,"fort":2,"ref":6,"will":5,"dr":"5/cold iron","weaknesses":["remorse"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +4 (1d6+1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"heat metal"}]}],"strength":12,"dexterity":15,"constitution":12,"intelligence":4,"wisdom":13,"charisma":9,"baseatk":2,"cmb":3,"cmd":15,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Perception","value":11},{"skill":"Stealth","value":9}],"languages":["Common","Sylvan"],"environments":["temperate forests","temperate plains"],"organizations":["solitary"],"treasure":"standard","description_visual":"This humanoid creature has the legs of a bald goat, a completely hairless body, and a horned head with a sinister expression.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Remorse","kind":"Ex","details":"Whenever a forlarren kills a living creature, it must make a DC 15 Will save to avoid becoming overwhelmed with remorse. If it fails this save, the forlarren becomes nauseated for 1d6 rounds. This is a mind-affecting effect."}],"description":"A nymph's charm and beauty are such that she can seduce nearly any creature that she sets her attentions on-and often, unfortunately, creatures she would rather not consort with.\n\nWhen a nymph catches the attention of a fiend and the fiend takes advantage of the creature, the resulting offspring isn't always a half-fiend.\n\nRoughly one in 20 such incidents results instead in a strange creature known as a forlarren-a unique creature that possesses its own unusual abilities and qualities.\n\nFew nymphs survive the ordeal of giving birth to a forlarren; those who do might attempt to raise their children in loving environments, but the evil that lurks in a forlarren's soul is powerful. In most cases where a nymph attempts to raise a forlarren child, it's only a matter of time before the forlarren grows resentful and its evil nature compels it to murder its mother.\n\nMost forlarrens are female, and few are capable of conceiving children of their own. A forlarren grows to adulthood with astonishing speed, reaching full growth in only a year-even those who come into the world as orphans are capable of defending themselves and seeking out food. Yet despite the rapidity with which they reach maturity, few forlarrens survive to adulthood. Cast out from both sylvan and fiendish society, the typical forlarren is a lonely creature, cursed by its own existence. It detests itself and everything it sees, and soon becomes consumed by hatred of life itself. The forlarren vents its rage on good and evil alike, lashing out at anything that approaches it.\n\nThe forlarren attacks with its clawed hands, typically focusing on a single opponent at a time and attacking until it or its opponent is slain. Yet curiously, when a forlarren succeeds in killing an opponent, the kindly traits of its fey mother sometimes surface, and it shows profound remorse for its cruelty. With such a pendulum of erratic behavior, it is no wonder that forlarrens are all but incapable of forming lasting friendships-even with others of their own kind.\n\nThe majority of forlarrens inherit little in the way of the magical abilities possessed by their fey mothers, but they do gain a small measure of the powers of their fiendish fathers. In most cases, this manifests as the ability to use heat metal three times per day, but some forlarren instead gain a different spell-like ability chosen from the following list: chill metal, flame blade, flaming sphere, gust of wind, summon swarm, or warp wood.\n\nA forlarren stands 6 ft. tall and weighs about 160 pounds.\n\nIn theory, these creatures can live for hundreds of years, but most perish through violence before they turn 10.","ecology":"","habitat_society":""},{"name":"Fungus Leshy","cr":2,"xp":600,"alignment":"N","size":"Small","type":"plant","subtypes":["leshy","shapechanger"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size, +0 natural","hp":15,"hd":"2d8+6","hdvalue":2,"fort":6,"ref":2,"will":2,"immunities":["electricity","sonic","plant traits"],"speed":[{"type":"land","speed":20}],"melee":"bite +2 (1d6), 2 claws +2 (1d3)","ranged":"puffball +4 (1 plus spores)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spores"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"}]}],"strength":10,"dexterity":15,"constitution":16,"intelligence":7,"wisdom":14,"charisma":15,"baseatk":1,"cmb":0,"cmd":12,"feats":[{"feat":"Blind-Fight"}],"skills":[{"skill":"Stealth","value":10,"special":"+14 in swamps and underground"},{"skill":"Survival","value":3,"special":"+7 in swamps and underground"}],"languages":["Druidic","Sylvan","plantspeech (fungi)"],"sq":[{"type":"change shape","details":"Small fungus; tree shape"},{"type":"verdant burst"}],"environments":["any swamps","any underground"],"organizations":["solitary","cluster (2-16)"],"treasure":"standard","description_visual":"Mismatched eyes dot this plant creature's thick mushroom cap, while below works an overlarge maw set with pale fungal teeth.","group":"Leshy","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Puffball","kind":"Ex","details":"A fungus leshy can spit a puffball as a standard action. If it hits, this attack deals 1 point of damage (this damage isn't modified by Strength) and affects the target struck (but not adjacent targets) with the fungus leshy's spores. The puffball has a range increment of 20 ft."},{"type":"Spores","kind":"Ex","details":"A fungus leshy is riddled with molds and spores. Anytime a fungus leshy takes damage, a cloud of spores bursts from its body, forcing all adjacent creatures to make a DC 14 Fortitude save or have their vision reduced to 10 ft. for 1 minute. Spending a full-round action to wash one's eyes with water ends this effect. The save DC is Constitution-based."}],"description":"Keepers of cavernous mushroom forests and rotting compost pits deep within the swamp, fungus leshys preside over subterranean growth and the rot that fertilizes new life. Among the most alien and monstrous-looking of all leshys, these tiny rot farmers' frightening appearance has more to do with the asymmetrical eeriness intrinsic to molds and fungi than an outward expression of evil. Like all their kin, fungus leshys vary widely in form, often adopting the colors and shapes of the mushrooms and other large fungi common to the areas they tend.\n\nFungus leshys are spawned from realms of underground wonder or the rotting places of the natural world. They perform an important service in the lands they keep, encouraging the growth of fungi, transporting rotting material to fertilize other plants, and making the most use of growth that has died off. Fungus leshys are most active at night and spend the day in the forms of plump fungi amid their ripest compost heaps or fungal glens.\n\nFungus leshys are 2 ft. tall and weigh 25 pounds, their spongy interiors full of hollows and fluffy spores.\n\nGROWING A FUNGUS LESHY\n\nA fungus leshy is usually grown amid the compost of a treant's groves, in dens of mold deep underground, or in eerie hillocks at the heart of dense swamplands.\n\nFUNGUS LESHY\n\nCL 8th; Price 2,500 gp\n\nRITUAL\n\nRequirements Knowledge (nature) 5 ranks, obscuring mist, plant growth, summon nature's ally II; Skill Knowledge (dungeoneering or nature) DC 14; Cost 1,250 gp","ecology":"","habitat_society":""},{"name":"Garden Ooze","cr":2,"xp":600,"alignment":"N","size":"Small","type":"ooze","init":3,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size, +0 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":3,"ref":4,"will":-4,"defensive_abilities":["ooze traits"],"immunities":["acid"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"slam +3 (1d4 plus 1d8 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid"},{"type":"stink"}],"strength":11,"dexterity":16,"constitution":15,"wisdom":1,"charisma":2,"baseatk":2,"cmb":1,"cmd":14,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":8}],"sq":[{"type":"camouflage"}],"environments":["any marshes","temperate forests","any urban"],"organizations":["solitary","pair","patch (3-5)"],"treasure":"none","description_visual":"What seems to be a mass of diseased fibers growing on a plant suddenly moves and slithers independently from its sickly host.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Acid","kind":"Ex","details":"A garden ooze excretes digestive acid that can dissolve flesh. Creatures made of harder materials or plant matter are immune to the ooze's acid."},{"type":"Camouflage","kind":"Ex","details":"A garden ooze is difficult to spot when it is at rest among plant growth of any type. A DC 15 Perception check is required to notice the ooze is a separate entity and not a diseased portion of the plant it rests upon. The ooze automatically hits with a slam against any creature that fails to notice the ooze and enters its square."},{"type":"Stink","kind":"Ex","details":"Once every 24 hours, a garden ooze can release foul-smelling gases in a 5-foot-radius spread centered on the ooze. The ooze usually does so after it is first injured. The stench of these vapors is overpowering during the first round it exists, causing living creatures within it to become sickened for 1d3 rounds (Fort DC 13 negates). This is a poison effect. The save DC is Constitution-based."}],"description":"A garden ooze is an animate, acidic mass of protoplasmic goo that dwells among foliage and scavenges proteins in the form of carrion or small animals that blunder into its vicinity. Although garden oozes are occasionally found in underground regions near the surface-such as sewers, sinkholes, and shallow caves-these oozes prefer the outdoors. One reason for this is that garden oozes are attracted to large collections of organic material where other tiny creatures might come to scavenge.\n\nQuick and cunning hunters when compared to most oozes, garden oozes are particularly dangerous because they readily attack creatures that wander nearby regardless of the creatures' size. Oozes that sense prey moving closer are likely to wait to attack until the potential meal is within reach. The oozes also give chase when prey flees. Garden oozes innately change hue to match the ground underneath them, so they can be hard to spot.\n\nWhen a garden ooze attacks, it lashes out with a whiplike appendage coated with a potent flesh-eating acid. If injured, the ooze releases a disgusting stench that makes it harder to fight off. Further, when one garden ooze attacks, any other garden oozes nearby join in, piling on and making escape all but impossible.\n\nFortunately for larger potential prey, most garden oozes are quite small, the largest among them reaching 3 ft. in diameter before they split into smaller oozes. These oozes are also known as rat-catcher oozes or compost oozes, and some brave gardeners actually encourage the growth of such oozes in their gardens as a way to combat pests. Once the pests are under control, however, the oozes themselves must be hunted and slain before the garden is safe to tend.","ecology":"","habitat_society":""},{"name":"Ghast","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"undead","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":17,"hd":"2d8+8","hdvalue":2,"fort":4,"ref":4,"will":7,"defensive_abilities":["channel resistance +2"],"speed":[{"type":"land","speed":30}],"melee":"bite +5 (1d6+3 plus disease and paralysis) and 2 claws +5 (1d6+3 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"paralysis","details":"1d4+1 rounds, DC 15, effects elves normally"},{"type":"stench"}],"strength":17,"dexterity":19,"intelligence":17,"wisdom":18,"charisma":18,"baseatk":1,"cmb":4,"cmd":18,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Climb","value":8},{"skill":"Perception","value":9},{"skill":"Stealth","value":9},{"skill":"Swim","value":4}],"languages":["Common"],"environments":["any land"],"organizations":["solitary","gang (2-4)","pack (7-12)"],"treasure":"standard","description_visual":"This humanoid creature has long, sharp teeth, and its pallid flesh is stretched tightly over its starved frame.","source":"PFRPG Bestiary","special_abilities":[{"type":"Disease","kind":"Su","details":"Ghoul Fever: Bite-injury; save Fort DC 15; onset 1 day; frequency 1 day; effect 1d3 Con and 1d3 Dex damage; cure 2 consecutive saves. The save DC is Charisma-based. A humanoid who dies of ghoul fever rises as a ghoul at the next midnight. A humanoid who becomes a ghoul in this way retains none of the abilities it possessed in life. It isn't under the control of any other ghouls, but it hungers for the flesh of the living and behaves like a normal ghoul in all respects. A humanoid of 4 Hit Dice or more rises as a ghast."},{"type":"Paralysis","kind":"Su","details":"Creatures damaged by a ghast's natural attacks must make a successful DC 15 Fortitude save or be paralyzed for 1d4+1 rounds. Paralyzed creatures cannot move, speak, or take any physical actions. The creature is rooted to the spot, frozen and helpless. Unlike ghouls, A ghast's paralysis even affects elves Unlike hold person and similar effects, a paralysis effect doesn't allow a new save each round. A winged creature flying in the air at the time that it is paralyzed cannot flap its wings and falls. A swimmer can't swim and may drown. The duration of the paralysis varies and is included in the creature's description."},{"type":"Stench","kind":"Ex","details":"Ghast's exude an overwhelming stink of death and corruption in a 10-foot radius. Those within the stench must succeed at a DC 15 Fortitude save, or be sickened for 1d6+4 minutes."}],"description":"A ghast's paralysis even affects elves. Ghasts roam in packs of their own kind or lead groups of common ghouls. The stink of death and corruption surrounding these creatures is overwhelming.","ecology":"","habitat_society":""},{"name":"Ghelarn","cr":2,"xp":600,"alignment":"N","size":"Large","type":"aberration","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"ac":14,"ac_touch":9,"ac_flat_footed":14,"ac_mods":"+5 natural, -1 size","hp":22,"hd":"3d8+9","hdvalue":3,"fort":4,"ref":1,"will":5,"defensive_abilities":["carapace"],"resists":[{"type":"fire","value":5}],"weaknesses":["vulnerable to sonic"],"speed":[{"type":"land","speed":30}],"melee":"2 tentacles +4 (1d6+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"entrap","details":"DC 14, 1d8 rounds, hardness 5, hp 8"},{"type":"leeching tendrils"}],"strength":17,"dexterity":10,"constitution":16,"intelligence":3,"wisdom":14,"charisma":3,"baseatk":2,"cmb":6,"cmd":16,"feats":[{"feat":"Combat Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":4,"special":"+14 in deserts"}],"sq":[{"type":"hibernate"}],"environments":["cold deserts","temperate deserts"],"organizations":["solitary"],"treasure":"none","description_visual":"Purple tentacles emerge from a white, coral-like rock formation, tracing whirled patterns in the surrounding sand.","source":"AP 85","special_abilities":[{"type":"Carapace","kind":"Ex","details":"A ghelarn typically shelters within a hardened, rocklike shell that houses all of its vital organs. By withdrawing its tentacles and sensory stalks into its shell, the ghelarn gains total cover until the beginning of its next turn. The shell doesn't provide cover against targeted spells, and the ghelarn's movement is limited to downward burrowing during this time. The benefits of the shell can be lost if sundered (hardness 5, 8 hit points, regenerates in 2d6 days), and a ghelarn caught without its carapace loses its natural armor bonus."},{"type":"Entrap","kind":"Ex","details":"A ghelarn secretes a quagmire of sticky fluid a few ft. below the sand where it lives. This fluid extends in a 10-foot radius around the creature and acts to trap victims, making it easier for the ghelarn to attack prey with its tentacles or feed upon it with its leeching tendrils. This otherwise acts as the entrap universal monster rule."},{"type":"Hibernate","kind":"Ex","details":"When food is scarce, a ghelarn can enter a state of hibernation for an indefinite period of time. When it enters hibernation, the ghelarn nestles itself in the sand and fills in its porous carapace with sticky excretions that quickly harden to seal the creature from the elements. When hibernating, the ghelarn doesn't have to eat or drink. A ghelarn remains in a state of hibernation until it senses another living creature within 10 ft., at which point it dissolves the seals on its carapace over the course of 1d4 minutes."},{"type":"Leeching Tendrils","kind":"Ex","details":"A living creature that spends more than a single round ensnared within a ghelarn's entrapping fluid becomes targeted by invasive tendrils from the ghelarn's lower body. These feeding stalks deal 1 point of bleed damage each round, and continue to do so for as long as a victim remains within the area of the ghelarn's entrapping fluid."}],"description":"Born on the desert plain of an alien world, the soft-bodied ghelarn is a non-aquatic arthropod living within a shell-like exoskeleton manufactured from its own hardened secretions. This outer carapace contains many perforations, similar to dry coral or air-blasted stone, providing ample room from which the ghelarn can extend its outer extremities and explore the world. Chief among these appendages are two main tentacles that it uses to pull itself through the upper layers of sand within its native home, burrowing just below the surface while its hardened carapace remains above ground. As a result, ghelarns give the impression of ambulatory stone formations when traveling, but they can also abandon their shells entirely and delve deeper into the sand to avoid predators.\n\nPatient, quiet creatures, ghelarns prefer to ambush prey, waiting until suitable meals wander within reach of their tentacles or into the sticky quagmires they create just below the surface around their nesting grounds. Helpless victims soon find themselves pulled into the sand as the ghelarn extends invasive tendrils from its lower body. These lesser tentacles slowly bleed away moisture from anyone trapped in the ooze, leaving behind little more than dried husks and bones for scavengers to find, along with whatever equipment such victims may have carried.\n\nEcology\n\nDuring the creatures' spawning season, an entire clutch of ghelarns produces a variant musk in their secretions to attract one another. Some travel for miles in search of this scent, and the resulting orgy once a group gathers allows for a communal intermingling of reproductive oils. This impregnates multiple ghelarn at the same time, enabling them to spawn new offspring as they separate again. A typical ghelarn can create 1d3 young, which gestate for consecutive 3-month periods rather than being born all at once. Pregnant ghelarns abandon these young to fend for themselves almost as soon as they're born, moving to another region to birth more offspring rather than leaving them within the same area to compete for resources.\n\nIt takes a newborn ghelarn about 2 weeks before it can muster enough secretions to form a hardened shell of its own. During this time, it stays deep below the earth, seeking nourishment and moisture trapped in the desert soil rather than risking its vulnerable body to predators above ground. Once fully matured, it pushes upward, its shell rising from the sand to mark its domain. Sentient creatures wisely avoid these areas, though it's often hard\n\nto tell empty shells from a living ghelarn's hunting grounds. Many societies find the abandoned and cast-off shells useful for making tools and crafting weapons and armor. As a result, ghelarn habitats frequently draw those seeking to harvest them as a resource. Unfortunately for the scavengers, these shells also attract young ghelarns who haven't yet formed their own and seek to use the abandoned ones as temporary homes.\n\nHabitat & Society\n\nGhelarns typically live solitary lives. The extreme nature of their native habitat causes them to separate and spread out to avoid overhunting an area. They sometimes cooperate in pairs or packs known as clutches to defend themselves, but more frequently do so in preparation for mating season, so they can drag down large prey that they leave behind for their new offspring to feed upon. Sometimes a clutch will gather in geologically unstable regions, where quakes and tremors draw their interest. Mostly, they migrate in seemingly aimless patterns, driven away from the harsh sounds of overhead thunderstorms, as the noise causes them acute pain.\n\nThe rudimentary sentience of ghelarns places them just above animal-level intelligence. Though they have no real language of their own, they communicate warnings or call for help by turning their porous shells into the wind and adjusting the flow with their tentacles, allowing air to pass through the openings, and creating a musical \"voice\" similar to wind instruments. Each ghelarn's voice is distinctly different from any other ghelarn. Some societies have also learned to domesticate young ghelarns-these cultures train them to understand simple commands and use them as guard animals.\n\nNoble Ghelarns\n\nOccasionally, evolution gives rise to a more advanced breed of ghelarn. These specimens have both the advanced and giant simple templates, and prove more intelligent than their lesser kin. The shell of a noble ghelarn encompasses a much greater area, appearing more like an outcropping of rock or a small hillside. This grants them the freeze special quality to appear as such, allowing them to take 20 on their Stealth checks to hide in plain sight. Noble ghelarns sometimes remain hidden within these massive shells and purposefully suppress their entrapping ooze in order to dupe other creatures into seeking shelter next to them. While the tall shell certainly provides shade from the sun and a windbreak against desert storms, those camping near a noble ghelarn inevitably find themselves assaulted during the night by the creature's invasive tendrils. These appendages are more leechlike than the painful barbs of lesser ghelarns and require a DC 20 Perception check for sleeping creatures to notice.","ecology":"During the creatures' spawning season, an entire clutch of ghelarns produces a variant musk in their secretions to attract one another. Some travel for miles in search of this scent, and the resulting orgy once a group gathers allows for a communal intermingling of reproductive oils. This impregnates multiple ghelarn at the same time, enabling them to spawn new offspring as they separate again. A typical ghelarn can create 1d3 young, which gestate for consecutive 3-month periods rather than being born all at once. Pregnant ghelarns abandon these young to fend for themselves almost as soon as they're born, moving to another region to birth more offspring rather than leaving them within the same area to compete for resources.\n\nIt takes a newborn ghelarn about 2 weeks before it can muster enough secretions to form a hardened shell of its own. During this time, it stays deep below the earth, seeking nourishment and moisture trapped in the desert soil rather than risking its vulnerable body to predators above ground. Once fully matured, it pushes upward, its shell rising from the sand to mark its domain. Sentient creatures wisely avoid these areas, though it's often hard\n\nto tell empty shells from a living ghelarn's hunting grounds. Many societies find the abandoned and cast-off shells useful for making tools and crafting weapons and armor. As a result, ghelarn habitats frequently draw those seeking to harvest them as a resource. Unfortunately for the scavengers, these shells also attract young ghelarns who haven't yet formed their own and seek to use the abandoned ones as temporary homes.","habitat_society":"Ghelarns typically live solitary lives. The extreme nature of their native habitat causes them to separate and spread out to avoid overhunting an area. They sometimes cooperate in pairs or packs known as clutches to defend themselves, but more frequently do so in preparation for mating season, so they can drag down large prey that they leave behind for their new offspring to feed upon. Sometimes a clutch will gather in geologically unstable regions, where quakes and tremors draw their interest. Mostly, they migrate in seemingly aimless patterns, driven away from the harsh sounds of overhead thunderstorms, as the noise causes them acute pain.\n\nThe rudimentary sentience of ghelarns places them just above animal-level intelligence. Though they have no real language of their own, they communicate warnings or call for help by turning their porous shells into the wind and adjusting the flow with their tentacles, allowing air to pass through the openings, and creating a musical \"voice\" similar to wind instruments. Each ghelarn's voice is distinctly different from any other ghelarn. Some societies have also learned to domesticate young ghelarns-these cultures train them to understand simple commands and use them as guard animals.\n\nNoble Ghelarns\n\nOccasionally, evolution gives rise to a more advanced breed of ghelarn. These specimens have both the advanced and giant simple templates, and prove more intelligent than their lesser kin. The shell of a noble ghelarn encompasses a much greater area, appearing more like an outcropping of rock or a small hillside. This grants them the freeze special quality to appear as such, allowing them to take 20 on their Stealth checks to hide in plain sight. Noble ghelarns sometimes remain hidden within these massive shells and purposefully suppress their entrapping ooze in order to dupe other creatures into seeking shelter next to them. While the tall shell certainly provides shade from the sun and a windbreak against desert storms, those camping near a noble ghelarn inevitably find themselves assaulted during the night by the creature's invasive tendrils. These appendages are more leechlike than the painful barbs of lesser ghelarns and require a DC 20 Perception check for sleeping creatures to notice."},{"name":"Giant Ant","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":15,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+5 natural","hp":18,"hd":"2d8+9","hdvalue":2,"fort":6,"ref":0,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":50},{"type":"climb","speed":20}],"melee":"bite +3 (1d6+2 plus grab), sting +3 (1d4+2 plus poison)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":10,"constitution":17,"wisdom":13,"charisma":11,"baseatk":1,"cmb":3,"cmb_special":"+4 vs. grapple","cmd":13,"cmd_special":"+8 vs. trip","feats":[{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":5},{"skill":"Survival","value":5}],"environments":["any"],"organizations":["solitary","pair","gang (3-6)","hive (7-18 plus 10-100 workers, 2-8 drones, and 1 queen)"],"treasure":"none","description_visual":"A thin, six-legged ant the size of a pony stands at the ready, its mandibles chittering and its stinger dripping with venom.","group":"Ant","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 14; frequency 1/round for 4 rounds; effect 1d2 Str; cure 1 save"}],"description":"Giant ants are as industrious as their normal-sized kin. While their nests generally don't consist of thousands, their greatly increased size more than compensates. The statistics given above are for soldier ants-the variety most commonly encountered. The following simple templates can be used to create variants of the standard soldier ant. Worker (-1 CR) Worker ants don't have a poison sting attack or a grab special attack. Drone (+1 CR) Drones have the advanced simple template and a fly speed of 30 ft. (average). Queen (+2 CR) The queen of a nest is an immense, bloated creature. She gains the advanced and the giant simple templates, but drops her speed to 10 ft. and loses her climb speed entirely.","ecology":"","habitat_society":""}];
